INSERT INTO `wp_posts` VALUES (267,1,'2026-09-03 16:03:57','2026-09-03 16:03:57','<h2>What\'s New?</h2>										<a href=\"#\">\n				<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 20 20\" fill=\"none\"><path d=\"M3 9.83301L18 9.83301\" stroke=\"white\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path><path d=\"M12 4L17.8333 9.83333L12 15.6667\" stroke=\"white\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path></svg>			\n									Zapier Now Connected\n					</a>\n									<p>Manage your allSales &amp; Analytics in one place</p>		<p>Track custom events, increase from submissions, optimise conversion rates and optimise your sales flow with appnetic.</p>								<a href=\"#\">\n									Book your demo\n					</a>\n																			<img width=\"1880\" height=\"980\" src=\"http://secondwebsite.local/wp-content/uploads/2026/05/Hero-Banner.png\" alt=\"\" decoding=\"async\" />																<style>\n.elementor-widget .elementor-icon-list-items {\n    list-style-type: none !important;\n    margin: 0 !important;\n    padding: 0 !important;\n}\nhtml, body {\n   overflow-x: hidden;\n}\na{\n    text-decoration: none !important;\n}\n.hero-wrapper::after {\n  content: \"\";\n  display: block;\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 400px;\n  background-image: url(\'https://kitpapa.net/appnetic/wp-content/uploads/2025/06/Mask-group-1.png\');\n  background-repeat: no-repeat;\n  background-size: 100% auto;\n  background-position: top center;\n  z-index: 1;\n  pointer-events: none;\n}\n.hero-what-new-wrapper {\nbackground: #4300EE;\nbox-shadow: inset 1px 1px 6px 2px rgba(255, 255, 255, 0.1), inset -1px -1px 6px 2px rgba(255, 255, 255, 0.1);\nborder-radius: 100px;\n}  \n.hero-connected-button .elementor-button-icon {\n    font-size: 16px;\n}\n.hero-connected-button .elementor-button-icon svg {\n    fill: none !important;\n}\n.button-shadow .elementor-button {\n    background: #4300EE;\n    box-shadow: \n        0 0 0px 0px rgba(67, 0, 238, 0),\n        inset -2px -2px 12px 2px rgba(255, 255, 255, 0.16), \n        inset 2px 2px 10px 2px rgba(255, 255, 255, 0.16);\n    border-radius: 100px;\n    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);\n    transform: scale(1);\n    position: relative;\n    z-index: 1;\n}\n.button-shadow .elementor-button:hover {\n    transform: scale(1.05);\n    box-shadow: \n        0 0 20px rgba(67, 0, 238, 0.8),\n        0 0 40px rgba(67, 0, 238, 0.6),\n        inset -2px -2px 12px 2px rgba(255, 255, 255, 0.16),\n        inset 2px 2px 10px 2px rgba(255, 255, 255, 0.16);\n}\n.button-shadow .elementor-button-icon {\n    font-size: 20px;\n}\n.button-shadow .elementor-button-icon svg {\n    fill: none !important;\n}\n.product-item-bg {\n      background: \n    linear-gradient(142.02deg, rgba(0, 16, 255, 0) 1.07%, rgba(242, 0, 255, 0.1) 97.45%),\n    linear-gradient(142.02deg, rgba(0, 16, 255, 0.1) 1.07%, rgba(242, 0, 255, 0.1) 97.45%);\n  -webkit-backdrop-filter: blur(20.7357px);\n  backdrop-filter: blur(20.7357px);\n}\n.gradient-border::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: 50%;\n  transform: translateX(-50%);\n  width: 100%;\n  height: 1px;\n  background: radial-gradient(circle at center, #4550F1 0%, rgba(55, 37, 49, 0) 80%) !important;\n  background-color: transparent !important;\n  border: none !important;\n  border-radius: 20px;\n  pointer-events: none;\n  z-index: 2;\n}\n.gradient-border::after {\n  content: \"\";\n  position: absolute;\n  bottom: 0;\n  left: 50%;\n  transform: translateX(-50%);\n  width: 100%;\n  height: 1px;\n  background: radial-gradient(circle at center, #4550F1 0%, rgba(55, 37, 49, 0) 80%) !important;\n  background-color: transparent !important;\n  border: none !important;\n  border-radius: 20px;\n  pointer-events: none;\n  z-index: 2;\n}\n.slider-item {\n      background: linear-gradient(142.02deg, rgba(61, 35, 178, 0.1) 1.07%, rgba(242, 0, 255, 0.1) 97.45%);\n  backdrop-filter: blur(20.7357px);\n  -webkit-backdrop-filter: blur(20.7357px);\n  border-radius: 20px;\n}\n.parent-container {\n  width: 100%;\n  overflow: hidden;\n  position: relative;\n}\n.slider-track-left, .slider-track-right {\n  display: flex;\n  width: max-content;\n}\n.slider-track-left {\n  animation: slideLeft 40s linear infinite;\n}\n.slider-track-right {\n  animation: slideRight 40s linear infinite;\n}\n.slider-track-left:hover,\n.slider-track-right:hover {\n  animation-play-state: paused;\n}\n@keyframes slideLeft {\n  0% {\n    transform: translateX(0);\n  }\n  100% {\n    transform: translateX(calc(-100% / 2));\n  }\n}\n@keyframes slideRight {\n  0% {\n    transform: translateX(calc(-100% / 2));\n  }\n  100% {\n    transform: translateX(0);\n  }\n}\n.slider-content {\n  display: flex !important;\n  flex-wrap: nowrap !important;\n}\n.parent-container::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background: linear-gradient(270deg, #030116 0%, rgba(3, 1, 22, 0) 30%, rgba(3, 1, 22, 0) 70%, #030116 100%);\n  pointer-events: none;\n  z-index: 2; \n}\n.logo-section::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background: linear-gradient(90deg, #030116 0%, rgba(3, 1, 22, 0) 30%, rgba(3, 1, 22, 0) 70%, #030116 100%);\n  pointer-events: none;\n  z-index: 2;\n}\n.pricing-section {\n    background: #020219;\nbox-shadow: 0px -45px 85px rgba(1, 13, 182, 0.55), 0px 45px 85px rgba(1, 13, 182, 0.55);\nborder-radius: 12px;\n}\n.price-icon-list .elementor-icon-list-item {\n    display: flex;\n    padding: 5px 6px 5px 6px;\n    background: rgba(255, 255, 255, 0.03);\n    border-radius: 100px;\n    margin-bottom: 8px;\n}\n.price-list-opacity {\n    opacity: 0.2;\n}\n</style>\n<style>\nbody:not(.elementor-editor-active) .monthly-plan,\nbody:not(.elementor-editor-active) .annual-plan {\n  display: none;\n}\nbody:not(.elementor-editor-active) .monthly-plan.show {\n  display: block;\n}\nbody:not(.elementor-editor-active) .annual-plan.show {\n  display: block;\n}\n</style>\n					<h2>Product</h2>					<p>Track the things that matter  most to you.</p>					<h2>Simple Analytics</h2>		<p>Empower your choices with insights derived from our real-time data streams.</p>					\n			<img \n					data-interaction-id=\"6df8d40\" \n		 data-e-type=\"widget\" data-id=\"6df8d40\"\n									id=\"36\"\n												src=\"http://secondwebsite.local/wp-content/uploads/2026/05/Card_mask-group.png\"\n												width=\"725\"\n												height=\"308\"\n												srcset=\"\"\n												alt=\"\"\n						/>\n						<h2>Generate <br>\nReports with Ease</h2>		<p>Easily download reports comprising of data from your sales reps or a custom date range.</p>					\n			<img \n					data-interaction-id=\"48507e0\" \n		 data-e-type=\"widget\" data-id=\"48507e0\"\n									id=\"37\"\n												src=\"http://secondwebsite.local/wp-content/uploads/2026/05/Card_mask-group-1.png\"\n												width=\"696\"\n												height=\"452\"\n												srcset=\"\"\n												alt=\"\"\n						/>\n						<h2>Transparent <br>\nSales Tracking</h2>		<p>Keep an eye on sales by tracking the revenue generated by every team member.</p>					\n			<img \n					data-interaction-id=\"364b0fc\" \n		 data-e-type=\"widget\" data-id=\"364b0fc\"\n									id=\"38\"\n												src=\"http://secondwebsite.local/wp-content/uploads/2026/05/Card_mask-group-2-1.png\"\n												width=\"696\"\n												height=\"508\"\n												srcset=\"\"\n												alt=\"\"\n						/>\n						<h2>Invite Unlimited Team  Members</h2>		<p>Don\'t leave the team behind and easily invite unlimited team members onboard.</p>					\n			<img \n					data-interaction-id=\"3f5c4e0\" \n		 data-e-type=\"widget\" data-id=\"3f5c4e0\"\n									id=\"35\"\n												src=\"http://secondwebsite.local/wp-content/uploads/2026/05/Card.png\"\n												width=\"818\"\n					